import Combine
import Foundation
import SwiftUI

final class APITestRunner: ObservableObject {
  @Published private(set) var lastResult = ""
  @Published private(set) var isLoading = false

  func run(_ name: String, action: @escaping () async throws -> Any) {
    Task {
      await MainActor.run {
        isLoading = true
      }

      let start = CFAbsoluteTimeGetCurrent()

      do {
        let result = try await action()
        let elapsed = String(format: "%.2f", CFAbsoluteTimeGetCurrent() - start)
        let text = "✅ [\(name)] (\(elapsed)s)\n\(APITestRenderer.render(result))"

        await MainActor.run {
          lastResult = text
          isLoading = false
        }
      } catch {
        let elapsed = String(format: "%.2f", CFAbsoluteTimeGetCurrent() - start)
        let text = "❌ [\(name)] (\(elapsed)s)\n\(String(describing: error))"

        await MainActor.run {
          lastResult = text
          isLoading = false
        }
      }
    }
  }
}

struct APITestScreen<Content: View>: View {
  let title: String
  let content: (APITestRunner) -> Content

  @StateObject private var runner = APITestRunner()

  init(title: String, @ViewBuilder content: @escaping (APITestRunner) -> Content) {
    self.title = title
    self.content = content
  }

  var body: some View {
    List {
      Section("Result") {
        if runner.isLoading {
          ProgressView()
        }

        Text(runner.lastResult.isEmpty ? "-" : runner.lastResult)
          .pretendard(.caption1)
          .textSelection(.enabled)
      }

      content(runner)
    }
    .listStyle(.insetGrouped)
    .navigationTitle(title)
    .textInputAutocapitalization(.never)
    .autocorrectionDisabled()
  }
}

struct APITestActionButton: View {
  let title: String
  @ObservedObject var runner: APITestRunner
  let action: () async throws -> Any

  var body: some View {
    Button(title) {
      runner.run(title, action: action)
    }
    .disabled(runner.isLoading)
  }
}

struct APITestMenuRow: View {
  let title: String
  let subtitle: String

  var body: some View {
    VStack(alignment: .leading, spacing: 4) {
      Text(title)
        .pretendard(.body1)
      Text(subtitle)
        .pretendard(.caption1)
        .foregroundStyle(.secondary)
    }
    .padding(.vertical, 4)
  }
}

enum APITestInputError: LocalizedError {
  case required(String)
  case invalidInt(String)
  case invalidDouble(String)
  case invalidJSON(String)

  var errorDescription: String? {
    switch self {
    case let .required(field):
      return "\(field)은(는) 필수값입니다."
    case let .invalidInt(field):
      return "\(field)은(는) 정수 형식이어야 합니다."
    case let .invalidDouble(field):
      return "\(field)은(는) 숫자 형식이어야 합니다."
    case let .invalidJSON(field):
      return "\(field)은(는) JSON 형식이어야 합니다."
    }
  }
}

enum APITestRenderer {
  static func render(_ value: Any) -> String {
    switch value {
    case let value as String:
      return value
    case let value as URL:
      return value.absoluteString
    case let value as JSONValue:
      return prettyJSONString(value)
    default:
      return String(describing: value)
    }
  }

  private static func prettyJSONString<T: Encodable>(_ value: T) -> String {
    let encoder = JSONEncoder.api
    encoder.outputFormatting = [.prettyPrinted, .sortedKeys]

    guard
      let data = try? encoder.encode(value),
      let string = String(data: data, encoding: .utf8)
    else {
      return String(describing: value)
    }

    return string
  }
}

func optionalString(_ text: String) -> String? {
  let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
  return trimmed.isEmpty ? nil : trimmed
}

func requiredString(_ text: String, field: String) throws -> String {
  guard let value = optionalString(text) else {
    throw APITestInputError.required(field)
  }
  return value
}

func csvValues(_ text: String) -> [String]? {
  let values = text
    .split(separator: ",")
    .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    .filter { !$0.isEmpty }

  return values.isEmpty ? nil : values
}

func optionalInt(_ text: String, field: String) throws -> Int? {
  guard let value = optionalString(text) else { return nil }
  guard let intValue = Int(value) else {
    throw APITestInputError.invalidInt(field)
  }
  return intValue
}

func requiredInt(_ text: String, field: String) throws -> Int {
  guard let value = try optionalInt(text, field: field) else {
    throw APITestInputError.required(field)
  }
  return value
}

func optionalDouble(_ text: String, field: String) throws -> Double? {
  guard let value = optionalString(text) else { return nil }
  guard let doubleValue = Double(value) else {
    throw APITestInputError.invalidDouble(field)
  }
  return doubleValue
}

func requiredDouble(_ text: String, field: String) throws -> Double {
  guard let value = try optionalDouble(text, field: field) else {
    throw APITestInputError.required(field)
  }
  return value
}

func optionalJSONValue(_ text: String, field: String) throws -> JSONValue? {
  guard let value = optionalString(text) else { return nil }

  guard let data = value.data(using: .utf8) else {
    throw APITestInputError.invalidJSON(field)
  }

  let object: Any

  do {
    object = try JSONSerialization.jsonObject(with: data)
  } catch {
    throw APITestInputError.invalidJSON(field)
  }

  return try jsonValue(from: object, field: field)
}

func requiredJSONValue(_ text: String, field: String) throws -> JSONValue {
  guard let value = try optionalJSONValue(text, field: field) else {
    throw APITestInputError.required(field)
  }
  return value
}

/// JSON 텍스트를 임의의 Decodable DTO로 변환한다. Debug 화면에서 raw JSON 입력을
/// 도메인 DTO로 그대로 흘려보내기 위해 사용한다.
func optionalDecodableJSON<T: Decodable>(_ text: String, field: String, as type: T.Type) throws -> T? {
  guard let value = optionalString(text) else { return nil }
  guard let data = value.data(using: .utf8) else {
    throw APITestInputError.invalidJSON(field)
  }
  do {
    return try JSONDecoder.api.decode(T.self, from: data)
  } catch {
    throw APITestInputError.invalidJSON(field)
  }
}

func requiredDecodableJSON<T: Decodable>(_ text: String, field: String, as type: T.Type) throws -> T {
  guard let value = try optionalDecodableJSON(text, field: field, as: type) else {
    throw APITestInputError.required(field)
  }
  return value
}

private func jsonValue(from object: Any, field: String) throws -> JSONValue {
  switch object {
  case let value as String:
    return .string(value)
  case let value as NSNumber:
    if CFGetTypeID(value) == CFBooleanGetTypeID() {
      return .boolean(value.boolValue)
    }
    return .number(value.doubleValue)
  case let value as [String: Any]:
    return .object(
      try Dictionary(uniqueKeysWithValues: value.map { key, value in
        (key, try jsonValue(from: value, field: field))
      })
    )
  case let value as [Any]:
    return .array(try value.map { try jsonValue(from: $0, field: field) })
  case _ as NSNull:
    return .null
  default:
    throw APITestInputError.invalidJSON(field)
  }
}

private let samplePNGData = Data(
  base64Encoded: "-"
) ?? Data()

private let fallbackSamplePNGData = Data(
  base64Encoded: "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a5WQAAAAASUVORK5CYII="
) ?? Data()

func sampleImageUploadFile(named fileName: String) -> UploadFile {
  UploadFile(
    fieldName: "file",
    fileName: fileName,
    mimeType: "image/png",
    data: samplePNGData.isEmpty ? fallbackSamplePNGData : samplePNGData
  )
}

func sampleImageUploadFiles(prefix: String, count: Int = 1) -> [UploadFile] {
  (1...count).map { index in
    sampleImageUploadFile(named: "\(prefix)-\(index).png")
  }
}
